sp_BuscarEmpresa	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_BuscarEmpresa`(IN p_idEmpresa INT)\nBEGIN\n\n    SELECT idEmpresa, Nome, CNPJ, Telefone, Email, codigoMunicipio, fAtivo, dthCadastro\n\n    FROM Empresa\n\n    WHERE idEmpresa = p_idEmpresa;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
